const manifest={"id": "/sysadmin/mobile/", "name": "OpusChat", "short_name": "OpusChat", "description": "Your private Opus Zimbabwe website inbox and phone alerts.", "start_url": "/sysadmin/mobile/", "scope": "/sysadmin/", "display": "standalone", "background_color": "#000000", "theme_color": "#000000", "lang": "en", "icons": [{"src": "/opus-inbox-assets/icon-192-v6.png", "sizes": "192x192", "type": "image/png", "purpose": "any maskable"}, {"src": "/opus-inbox-assets/icon-512-v6.png", "sizes": "512x512", "type": "image/png", "purpose": "any maskable"}]};
const serviceWorker="const defaultInbox='/sysadmin/mobile/';\nfunction inboxURL(value){try{const url=new URL(value||defaultInbox,self.location.origin);if(url.origin===self.location.origin&&url.pathname==='/sysadmin/mobile/'){const chat=url.searchParams.get('chat');return defaultInbox+(chat&&/^[A-Za-z0-9_-]{1,100}$/.test(chat)?'?chat='+encodeURIComponent(chat):'');}if(url.origin===self.location.origin&&url.pathname==='/sysadmin/'&&url.searchParams.get('tool')==='whatsapp')return '/sysadmin/?tool=whatsapp';}catch{}return defaultInbox;}\nasync function testReceipt(payload,shown,error,clients,clientsKnown){try{const receipt=payload.receipt;if(!receipt||typeof receipt.token!=='string'||receipt.token.length!==72)return;const url=new URL(receipt.path,self.location.origin);if(url.origin!==self.location.origin||url.pathname!=='/api/chat/push-test-receipt')return;const windows=clients.filter(client=>new URL(client.url).pathname==='/sysadmin/mobile/');await fetch(url.href,{method:'POST',credentials:'omit',headers:{'content-type':'application/json'},body:JSON.stringify({token:receipt.token,shown,clients_known:clientsKnown,error:error?.name||null,window_clients:windows.length,visible_clients:windows.filter(client=>client.visibilityState==='visible').length}),signal:AbortSignal.timeout(8000)});}catch{}}\nself.addEventListener('push',event=>{let payload={};try{payload=event.data.json()}catch{}const icon=/^\\/opus-inbox-assets\\/notify-logo-(?:dark|light)-v(?:18|19)\\.png$/.test(payload.icon||'')?payload.icon:'/opus-inbox-assets/notify-logo-light-v19.png',url=inboxURL(payload.url);event.waitUntil((async()=>{let clients=[],clientsKnown=true;try{clients=await self.clients.matchAll({type:'window',includeUncontrolled:true});}catch{clientsKnown=false;}try{await self.registration.showNotification('OpusChat',{body:typeof payload.body==='string'?payload.body.slice(0,180):'A customer is waiting for your reply.',icon,badge:icon,tag:typeof payload.tag==='string'?payload.tag.slice(0,120):'opus-inbox',renotify:true,silent:false,timestamp:typeof payload.sentAt==='number'?payload.sentAt:Date.now(),data:{url,eventId:payload.eventId||'',sessionId:payload.sessionId||''},actions:[{action:'open',title:'Open chat'},{action:'dismiss',title:'Dismiss'}]});await testReceipt(payload,true,null,clients,clientsKnown);}catch(error){await testReceipt(payload,false,error,clients,clientsKnown);return;}for(const client of clients)if(new URL(client.url).pathname==='/sysadmin/mobile/')client.postMessage({type:'opus-inbox-updated',id:payload.eventId,sessionId:payload.sessionId});})());});\nself.addEventListener('notificationclick',event=>{event.notification.close();if(event.action==='dismiss')return;event.waitUntil((async()=>{const path=inboxURL(event.notification.data?.url),url=new URL(path,self.location.origin).href,clients=await self.clients.matchAll({type:'window',includeUncontrolled:true});const existing=clients.find(client=>new URL(client.url).origin===self.location.origin&&new URL(client.url).pathname==='/sysadmin/mobile/');if(existing&&path.startsWith(defaultInbox)){existing.postMessage({type:'opus-inbox-open',sessionId:event.notification.data?.sessionId||''});return existing.focus();}return self.clients.openWindow(url);})());});\nconst OPUS_APP_CACHE='opus-inbox-shell-v21';\nself.addEventListener('install',event=>{event.waitUntil(caches.open(OPUS_APP_CACHE).then(cache=>cache.addAll(['/opus-inbox-assets/icon-192-v6.png','/opus-inbox-assets/icon-512-v6.png','/opus-inbox-assets/notify-logo-light-v19.png','/opus-inbox-assets/notify-logo-dark-v19.png','/opus-inbox.webmanifest'])).then(()=>self.skipWaiting()));});\nself.addEventListener('activate',event=>{event.waitUntil((async()=>{const keys=await caches.keys(),target=await caches.open(OPUS_APP_CACHE);for(const key of keys.filter(key=>key.startsWith('opus-inbox-shell-')&&key!==OPUS_APP_CACHE)){const old=await caches.open(key);if(await old.match('/__opus_inbox_preference'))await target.put('/__opus_inbox_preference',new Response('1'));await caches.delete(key);}await self.clients.claim();})());});\nself.addEventListener('message',event=>{if(event.data?.type==='opus-inbox-app-preferred')event.waitUntil(caches.open(OPUS_APP_CACHE).then(cache=>cache.put('/__opus_inbox_preference',new Response('1'))));});\nself.addEventListener('fetch',event=>{\n const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin)return;\n if(url.pathname==='/sysadmin/mobile/'){\n  event.respondWith((async()=>{const cache=await caches.open(OPUS_APP_CACHE);try{const response=await fetch(event.request);if(response.ok&&response.headers.get('x-opus-inbox-app')==='1')await cache.put('/sysadmin/mobile/',response.clone());return response;}catch{const shell=await cache.match('/sysadmin/mobile/');if(shell){const headers=new Headers(shell.headers);headers.set('x-opus-inbox-offline','1');return new Response(shell.body,{status:shell.status,headers});}return new Response('Connect to the internet to open OpusChat for the first time.',{status:503,headers:{'content-type':'text/plain'}});}})());\n }else if(['/opus-inbox-assets/katex-0.19.1.min.js','/opus-inbox-assets/icon-192-v6.png','/opus-inbox-assets/icon-512-v6.png','/opus-inbox-assets/notify-logo-light-v19.png','/opus-inbox-assets/notify-logo-dark-v19.png','/opus-inbox.webmanifest','/opus-inbox-assets/wordmark-dark-v7.png','/opus-inbox-assets/wordmark-light-v7.png'].includes(url.pathname)||/^\\/opus-inbox-assets\\/(?:font-[a-z0-9-]+\\.woff2|message-fonts-v(?:10|15)\\.css)$/.test(url.pathname)){\n  event.respondWith(caches.open(OPUS_APP_CACHE).then(async cache=>(await cache.match(url.pathname))||(async()=>{const response=await fetch(event.request);if(response.ok&&!response.redirected)await cache.put(url.pathname,response.clone());return response;})()));\n }\n});\n";
export async function adminAppResponse(request,upstream=fetch){
 const url=new URL(request.url);
 if(fontAssets[url.pathname]&&request.method==='GET'){const asset=fontAssets[url.pathname];return new Response(Uint8Array.from(atob(asset.data),c=>c.charCodeAt(0)),{headers:{'content-type':asset.type,'cache-control':'public,max-age=31536000,immutable'}});}
 if(url.pathname==='/opus-inbox-assets/katex-0.19.1.min.js'&&request.method==='GET')return new Response(katexSource,{headers:{'content-type':'application/javascript','cache-control':'public,max-age=31536000,immutable'}});
 if(iconAssets[url.pathname]&&request.method==='GET')return new Response(Uint8Array.from(atob(iconAssets[url.pathname]),c=>c.charCodeAt(0)),{headers:{'content-type':'image/png','cache-control':'public,max-age=31536000,immutable'}});
 if(url.pathname==='/opus-inbox.webmanifest'&&request.method==='GET')return Response.json(manifest,{headers:{'content-type':'application/manifest+json','cache-control':'public,max-age=300'}});
 if(['/opus-notifications-sw.js','/opus-inbox-alerts-sw.js'].includes(url.pathname)&&request.method==='GET')return new Response(serviceWorker,{headers:{'content-type':'application/javascript','cache-control':'no-cache','service-worker-allowed':'/'}});
 if(!['/sysadmin/mobile','/sysadmin/mobile/'].includes(url.pathname))return null;
 if(request.method!=='GET')return new Response('Method not allowed',{status:405,headers:{allow:'GET'}});
 const check=await upstream(new Request(new URL('/api/admin/session',url),{method:'GET',headers:request.headers,redirect:'manual'}));
 if(!check.ok||!check.headers.get('content-type')?.includes('application/json'))return new Response('Sign in to your authorised Opus account to open this inbox.',{status:401,headers:{'content-type':'text/plain','cache-control':'no-store'}});
 const session=await check.json().catch(()=>null);
 if(!session||typeof session.email!=='string')return new Response('Administrator sign-in required.',{status:401,headers:{'cache-control':'no-store'}});
 if(url.pathname==='/sysadmin/mobile')return Response.redirect(new URL('/sysadmin/mobile/',url),308);
 return new Response(appHTML,{headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store','x-opus-inbox-app':'1','x-opus-inbox-version':'21','x-content-type-options':'nosniff','referrer-policy':'no-referrer','x-frame-options':'DENY','content-security-policy':"default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self' wss://opuszim.co.zw; frame-ancestors 'none'; base-uri 'self'; form-action 'self'"}});
}
